  updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha';
update public.pooja_steps set mantra_translit = replace(mantra_translit, 'suprasanno bhava', 'suprasannā bhava'),
  updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha';

-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  -- The rite is no longer a fragment.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Prana Pratishtha'
     and mantra_sanskrit like '%प्राण प्रतिष्ठार्थे जपे विनियोगः%'
     and mantra_sanskrit like '%करतलकरपृष्ठाभ्यां%'
     and mantra_sanskrit like '%दिग्बन्धः%'
     and mantra_sanskrit like '%अस्यां मूर्तौ प्राणस्तिष्ठतु%'
     and mantra_sanskrit like '%यावत्पूजावसानकाले%';
  if n <> 1 then raise exception 'the prana pratishtha is still missing a section'; end if;
  -- All nine bhava lines, as PHRASES. Counting the substring "bhava" finds
  -- eleven, because the dhyanam says "bhavatu sukhakaree".
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Prana Pratishtha'
     and mantra_sanskrit like '%' || 'आवाहितो भव' || '%'
     and mantra_sanskrit like '%' || 'स्थापितो भव' || '%'
     and mantra_sanskrit like '%' || 'सन्निहितो भव' || '%'
     and mantra_sanskrit like '%' || 'सन्निरुद्धो भव' || '%'
     and mantra_sanskrit like '%' || 'अवकुण्ठितो भव' || '%'
     and mantra_sanskrit like '%' || 'सुप्रीतो भव' || '%'
     and mantra_sanskrit like '%' || 'सुप्रसन्नो भव' || '%'
     and mantra_sanskrit like '%' || 'सुमुखो भव' || '%'
     and mantra_sanskrit like '%' || 'वरदो भव' || '%'
  ;
  if n <> 1 then raise exception 'a masculine bhava line is missing from the Ganesha step'; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Prana Pratishtha'
     and (mantra_sanskrit like '%आवाहिता भव%' or mantra_sanskrit like '%सुप्रसन्ना भव%'
          or mantra_sanskrit like '%वरदा भव%' or mantra_sanskrit like '%सुमुखी भव%');
  if n > 0 then raise exception 'a feminine bhava line is in the Ganesha step'; end if;
  -- and no masculine one left in the feminine set.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha'
     and (mantra_sanskrit like '%सुप्रसन्नो भव%' or mantra_tamil like '%ஸுப்ரஸந்நோ ப⁴வ%');
  if n > 0 then raise exception 'a masculine bhava line is still in the Varalakshmi step'; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha'
     and mantra_sanskrit like '%सुप्रसन्ना भव%';
  if n <> 1 then raise exception 'the Varalakshmi bhava line was not corrected'; end if;
  -- The nyasa syllables survived into every script.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Prana Pratishtha'
     and mantra_tamil like '%' || 'க்ரோம்' || '%'
     and mantra_translit like '%' || 'kroṃ' || '%';
  if n <> 1 then raise exception 'the bija syllables did not survive transliteration'; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;

